package com.ruoyi.ai.agent;
import com.ruoyi.ai.domain.AiWorkbook;
import com.ruoyi.ai.domain.dto.*;
import com.ruoyi.ai.mapper.AiWorkbookMapper;
import com.ruoyi.ai.service.impl.AiWorkbookServiceImpl;
import com.ruoyi.common.core.domain.R;
import com.ruoyi.common.core.context.SecurityContextHolder;
import junit.framework.TestCase;
import java.util.*;
import java.lang.reflect.*;

public class B10DraftBoundaryMysqlTest extends TestCase {
    private A1TestFixture f;private AiWorkbookServiceImpl books;private long book,main,source;private String first,sourceHead;private final String a="{\"v\":1}",b="{\"v\":2}",c="{\"v\":3}";
    protected void setUp() throws Exception {f=new A1TestFixture(true);book=f.seed("{\"v\":0}");f.identity();first=String.valueOf(commit(a).getData().get("commitId"));main=((Number)state().get("branchId")).longValue();books=new AiWorkbookServiceImpl();A1TestFixture.inject(books,"workbookMapper",f.workbooks);A1TestFixture.inject(books,"versionService",f.service);A1TestFixture.inject(books,"agentWriteGuard",f.guard);}
    protected void tearDown(){f.close();}
    private Map<String,Object> state(){return f.status(book);}
    private CommitRequest binding(String content){Map<String,Object> s=state();@SuppressWarnings("unchecked") Map<String,Object> d=(Map<String,Object>)s.get("workingState");CommitRequest r=new CommitRequest();r.setBranchId(((Number)s.get("branchId")).longValue());r.setBaseCommitId((String)s.get("headCommitId"));r.setBaseVersion(((Number)s.get("version")).longValue());r.setExpectedDraftVersion(d==null?-1L:((Number)d.get("version")).longValue());r.setLoadedRevision((String)s.get("loadedRevision"));r.setContent(content);r.setOperationId(UUID.randomUUID().toString());r.setCommitMessage("B10 draft test");r.setSource("manual");r.setExecutedChanges(Collections.singletonList(Collections.singletonMap("kind",(Object)"manual-snapshot")));return r;}
    private R<Map<String,Object>> commit(String content){CommitRequest r=binding(content);return f.tx.execute(tx->f.service.commit(book,r));}
    private void draft(String content){CommitRequest x=binding(content);WorkingStateRequest r=f.request(book,x.getExpectedDraftVersion(),x.getLoadedRevision(),content);r.setBaseVersion(x.getBaseVersion());r.setBaseCommitId(x.getBaseCommitId());assertEquals(200,f.save(book,r).getCode());}
    private DraftDeleteRequest deletion(){CommitRequest r=binding(null);DraftDeleteRequest d=new DraftDeleteRequest();d.setBranchId(r.getBranchId());d.setBaseCommitId(r.getBaseCommitId());d.setBaseVersion(r.getBaseVersion());d.setExpectedDraftVersion(r.getExpectedDraftVersion());d.setLoadedRevision(r.getLoadedRevision());d.setConfirmed(true);return d;}
    private R<Void> discard(DraftDeleteRequest d){f.identity();return f.tx.execute(tx->f.service.deleteWorkingState(book,d));}
    private String draftContent(long branch){return f.db.queryForObject("select cast(draft_snapshot as char character set utf8mb4) from ai_workbook_working_state where workbook_id=? and branch_id=?",String.class,book,branch);}
    private void checkout(long branch){CheckoutRequest r=f.checkoutRequest(book,branch);assertEquals(200,f.tx.execute(tx->f.service.checkout(book,branch,r)).getCode());}
    private void source(String mainDraft){if(mainDraft!=null)draft(mainDraft);BranchRequest r=new BranchRequest();r.setOperationId(UUID.randomUUID().toString());r.setBranchName("draft/test-"+UUID.randomUUID());r.setFromCommitId(first);source=((Number)f.tx.execute(tx->f.service.createBranch(book,r)).getData().get("branchId")).longValue();checkout(source);sourceHead=String.valueOf(commit(b).getData().get("commitId"));}
    private Map<String,Object> mainBinding(){for(Map<String,Object> branch:f.service.branches(book).getData())if("main".equals(branch.get("branchName")))return branch;throw new AssertionError("main missing");}
    private BranchIntegrateRequest mergeRequest(){Map<String,Object> m=mainBinding(),s=state();BranchIntegrateRequest r=new BranchIntegrateRequest();r.setOperationId(UUID.randomUUID().toString());r.setMainHeadCommitId((String)m.get("headCommitId"));r.setMainVersion(((Number)m.get("version")).longValue());r.setExpectedMainDraftVersion(((Number)m.get("draftVersion")).longValue());r.setMainLoadedRevision((String)m.get("loadedRevision"));r.setSourceHeadCommitId((String)s.get("headCommitId"));r.setSourceVersion(((Number)s.get("version")).longValue());return r;}
    private R<Map<String,Object>> merge(BranchIntegrateRequest r){return f.tx.execute(tx->f.service.fastForwardToMain(book,source,r));}
    private void mainUnchanged(){Map<String,Object> m=mainBinding();assertEquals(first,m.get("headCommitId"));assertEquals(1L,((Number)m.get("version")).longValue());assertEquals(source,((Number)state().get("branchId")).longValue());}
    private void failPointerUpdate() throws Exception {AiWorkbookMapper failing=(AiWorkbookMapper)Proxy.newProxyInstance(getClass().getClassLoader(),new Class<?>[]{AiWorkbookMapper.class},(proxy,method,args)->{if(method.getName().equals("updateVersionPointers"))return 0;try{return method.invoke(f.workbooks,args);}catch(InvocationTargetException e){throw e.getCause();}});A1TestFixture.inject(f.service,"workbookMapper",failing);}
    public void testLegacyExistingSaveCannotModifyHeadOrDraft(){draft(b);AiWorkbook request=f.workbooks.selectById(book,1L);request.setContent(c);request.setName("changed-legacy");assertEquals(409,f.tx.execute(tx->books.save(request)).getCode());assertEquals(b,draftContent(main));assertEquals(a,f.workbooks.selectById(book,1L).getContent());assertEquals(first,state().get("headCommitId"));}
    public void testNewImportAndRenameRemainAvailable(){AiWorkbook created=new AiWorkbook();created.setName("import-"+UUID.randomUUID());created.setType("imported");created.setContent(a);R<AiWorkbook> result=f.tx.execute(tx->books.save(created));assertEquals(200,result.getCode());assertNotNull(result.getData().getCurrentBranchId());AiWorkbook rename=new AiWorkbook();rename.setWorkbookId(book);rename.setName("renamed-"+UUID.randomUUID());assertEquals(200,f.tx.execute(tx->books.rename(rename)).getCode());assertEquals(a,state().get("content"));draft(b);assertEquals(200,commit(b).getCode());}
    public void testLegacyDeleteWithoutBindingFailsClosed(){draft(b);assertEquals(409,f.tx.execute(tx->f.service.deleteWorkingState(book,main)).getCode());assertEquals(b,draftContent(main));}
    public void testFreshDiscardReturnsHeadAndKeepsHistory(){draft(b);assertEquals(200,discard(deletion()).getCode());assertNull(state().get("workingState"));assertEquals(a,state().get("content"));assertEquals(first,state().get("headCommitId"));assertEquals(1,f.db.queryForObject("select count(*) from ai_workbook_commit where workbook_id=?",Integer.class,book).intValue());}
    public void testDiscardAfterCheckoutRestoresMirroredBookContent(){draft(b);BranchRequest r=new BranchRequest();r.setOperationId(UUID.randomUUID().toString());r.setBranchName("other-"+UUID.randomUUID());r.setFromCommitId(first);long other=((Number)f.tx.execute(tx->f.service.createBranch(book,r)).getData().get("branchId")).longValue();checkout(other);checkout(main);assertEquals(b,f.workbooks.selectById(book,1L).getContent());assertEquals(200,discard(deletion()).getCode());assertEquals(a,state().get("content"));assertEquals(a,f.workbooks.selectById(book,1L).getContent());}
    public void testStaleDiscardDoesNotDeleteNewerDraft(){draft(b);DraftDeleteRequest stale=deletion();draft(c);assertEquals(409,discard(stale).getCode());assertEquals(c,draftContent(main));}
    public void testMissingConfirmationAndForgedBindingsReject(){draft(b);for(int mode=0;mode<6;mode++){DraftDeleteRequest d=deletion();switch(mode){case 0:d.setConfirmed(false);break;case 1:d.setLoadedRevision("forged");break;case 2:d.setExpectedDraftVersion(null);break;case 3:d.setBaseVersion(999L);break;case 4:d.setBaseCommitId("forged");break;case 5:d.setBranchId(999L);break;}assertEquals(409,discard(d).getCode());}assertEquals(b,draftContent(main));}
    public void testCorruptHeadCannotConsumeDraft(){draft(b);DraftDeleteRequest d=deletion();f.db.update("update ai_workbook_snapshot set content_hash='forged' where commit_id=?",first);assertEquals(422,discard(d).getCode());assertEquals(b,draftContent(main));}
    public void testRepeatedDiscardCannotDeleteLaterDraft(){draft(b);DraftDeleteRequest old=deletion();assertEquals(200,discard(old).getCode());draft(c);assertEquals(409,discard(old).getCode());assertEquals(c,draftContent(main));}
    public void testRecreatedIdenticalDraftCannotMatchOldDiscardOrCommit(){draft(b);DraftDeleteRequest old=deletion();CommitRequest oldCommit=binding(b);assertEquals(200,discard(old).getCode());draft(b);assertEquals(0L,((Number)((Map<?,?>)state().get("workingState")).get("version")).longValue());assertEquals(409,discard(old).getCode());assertEquals(409,f.tx.execute(tx->f.service.commit(book,oldCommit)).getCode());assertEquals(b,draftContent(main));assertEquals(first,state().get("headCommitId"));}
    public void testCorruptMainSnapshotCannotConsumeKnownCleanDraft(){source(a);BranchIntegrateRequest r=mergeRequest();f.db.update("update ai_workbook_snapshot set content_hash='forged' where commit_id=?",first);assertEquals(422,merge(r).getCode());assertEquals(a,draftContent(main));mainUnchanged();}
    public void testDiscardPointerFailureRollsBackDeletedDraft() throws Exception {draft(b);DraftDeleteRequest d=deletion();failPointerUpdate();try{discard(d);fail("partial discard committed");}catch(IllegalStateException expected){}assertEquals(b,draftContent(main));assertEquals(a,f.workbooks.selectById(book,1L).getContent());}
    public void testMergeWithoutMainDraftPreservesBothHistories(){source(null);BranchIntegrateRequest r=mergeRequest();assertEquals(200,merge(r).getCode());assertEquals(main,((Number)state().get("branchId")).longValue());assertEquals(sourceHead,state().get("headCommitId"));assertEquals(b,state().get("content"));assertEquals(200,f.service.snapshot(book,first).getCode());assertEquals(2,f.db.queryForObject("select count(*) from ai_workbook_commit where workbook_id=?",Integer.class,book).intValue());assertEquals(409,merge(r).getCode());}
    public void testMergeCleanKnownMainDraftIsAtomic(){source(a);Map<String,Object> binding=mainBinding();assertEquals(0L,((Number)binding.get("draftVersion")).longValue());assertEquals(200,merge(mergeRequest()).getCode());assertNull(state().get("workingState"));assertEquals(b,state().get("content"));}
    public void testDirtyMainDraftNeverSilentlyConsumed(){source(c);assertEquals(409,merge(mergeRequest()).getCode());assertEquals(c,draftContent(main));mainUnchanged();}
    public void testNewMainDraftSinceListReadRejectsEvenIfClean(){source(null);BranchIntegrateRequest old=mergeRequest();checkout(main);draft(a);checkout(source);assertEquals(409,merge(old).getCode());assertEquals(a,draftContent(main));mainUnchanged();}
    public void testSameContentWithPendingAuditIsNotClean(){source(a);f.db.update("update ai_workbook_working_state set executed_changes_json='[{\"kind\":\"pending\"}]' where workbook_id=? and branch_id=?",book,main);assertEquals(409,merge(mergeRequest()).getCode());assertEquals(a,draftContent(main));mainUnchanged();}
    public void testStaleSourceAndSourceDraftCannotMerge(){source(null);BranchIntegrateRequest old=mergeRequest();assertEquals(200,commit(c).getCode());assertEquals(409,merge(old).getCode());draft(c);assertEquals(409,merge(mergeRequest()).getCode());mainUnchanged();}
    public void testMissingTargetBindingAndDivergentMainReject(){source(null);BranchIntegrateRequest missing=mergeRequest();missing.setMainLoadedRevision(null);assertEquals(409,merge(missing).getCode());checkout(main);assertEquals(200,commit(c).getCode());checkout(source);assertEquals(409,merge(mergeRequest()).getCode());assertEquals(source,((Number)state().get("branchId")).longValue());}
    public void testCorruptTargetOrSourceSnapshotsCannotMoveMain(){source(a);BranchIntegrateRequest r=mergeRequest();f.db.update("update ai_workbook_snapshot set content_hash='forged' where commit_id=?",sourceHead);assertEquals(422,merge(r).getCode());assertEquals(a,draftContent(main));mainUnchanged();}
    public void testMergePointerFailureRollsBackMainAndCleanDraft() throws Exception {source(a);BranchIntegrateRequest r=mergeRequest();failPointerUpdate();try{merge(r);fail("partial merge committed");}catch(IllegalStateException expected){}assertEquals(a,draftContent(main));mainUnchanged();}
    public void testLeaseAndOwnerProtectionRemain(){draft(b);DraftDeleteRequest d=deletion();f.db.update("insert into ai_agent_lease(workbook_id,run_id,fencing_token,expires_at) values(?,?,1,?)",book,"guard-test",System.currentTimeMillis()+120000);try{discard(d);fail("lease bypass");}catch(IllegalArgumentException expected){}f.db.update("update ai_agent_lease set run_id=null where workbook_id=?",book);SecurityContextHolder.setUserId("2");assertTrue(f.tx.execute(tx->f.service.deleteWorkingState(book,d)).getCode()!=200);f.identity();assertEquals(b,draftContent(main));}
}
